#pragma once
static void checkGeneratedRingCleanup(App& app,const std::string& dir){
    auto require=[](bool ok,const std::string& why){if(!ok)throw std::runtime_error("new ring cleanup: "+why);};
    const auto path=dir+"/local-open-chain.r62doc";if(GetFileAttributesW(W(path).c_str())==INVALID_FILE_ATTRIBUTES)return;
    Session prior;require(prior.open(path).ok(),"open preceding acyl-hydrazine stage");auto& s=app.s;s.cancel();s.doc=prior.doc;s.history.clear();s.selected.clear();s.input.bindDocument(s.doc.id());
    std::set<ObjectId> open;ObjectId donor=kInvalidObjectId,firstCarbon=kInvalidObjectId;for(const auto& a:s.doc.atoms().records())if(a.isAlive()){auto original=studio_mechanism_products::sourceAtom(s.doc,a.id);if(original>=201&&original<=221&&s.doc.extensions(ObjectRef(ObjectKind::Atom,a.id)).findValue("studio.test.local.open")){open.insert(a.id);if(original==221)donor=a.id;if(original==209)firstCarbon=a.id;}}
    require(open.size()==20&&donor!=kInvalidObjectId,"identify twenty-atom open-chain product and terminal N");ObjectId carbon=kInvalidObjectId,oxygen=kInvalidObjectId,leaving=kInvalidObjectId;
    for(auto id:open)if(id!=firstCarbon&&s.doc.atoms().alive(id)->element==6){ObjectId o=kInvalidObjectId,n=kInvalidObjectId;for(auto bid:s.doc.incidentBonds(id)){auto b=s.doc.bonds().alive(bid);auto other=b->beginAtom==id?b->endAtom:b->beginAtom;if(b->order==BondOrder::Double&&s.doc.atoms().alive(other)->element==8)o=other;if(s.doc.atoms().alive(other)->element==7)n=other;}if(o!=kInvalidObjectId&&n!=kInvalidObjectId){carbon=id;oxygen=o;leaving=n;}}
    require(carbon!=kInvalidObjectId&&leaving!=kInvalidObjectId,"identify second acyl group and benzylamine leaving atom");
    for(auto endpoints:std::vector<std::pair<ObjectRef,ObjectRef>>{{{ObjectKind::Bond,s.doc.bondBetween(carbon,oxygen)},{ObjectKind::Atom,oxygen}},{{ObjectKind::Atom,donor},{ObjectKind::Atom,carbon}},{{ObjectKind::Bond,s.doc.bondBetween(carbon,leaving)},{ObjectKind::Atom,leaving}}}){Vec2 a,b;arrows::mechanismAnchorPoint(s.doc,endpoints.first,&a);arrows::mechanismAnchorPoint(s.doc,endpoints.second,&b);auto p=arrows::resolvePreset(49,a,b,.6);p.mechanism=true;p.electronSource=endpoints.first;p.electronTarget=endpoints.second;p.head.atBegin=endpoints.first==ObjectRef(ObjectKind::Bond,s.doc.bondBetween(carbon,oxygen));arrows::routeMechanism(s.doc,p);ObjectId id;require(arrows::addArrow(s.doc,p,.6,&id).ok(),"draw intramolecular addition elimination");s.selected.emplace_back(ObjectKind::Arrow,id);}
    s.refresh();auto source=s.doc;auto before=s.doc.digest();auto count=s.doc.stats().aliveAtoms;app.generateMechanismStep(1);std::ofstream(dir+"/ring-cleanup-status.txt")<<app.status;require(s.doc.stats().aliveAtoms==count+20,"ring closure generates both products: "+app.status);
    std::map<ObjectId,ObjectId> product;for(auto ref:s.selected)if(ref.kind==ObjectKind::Atom)product[studio_mechanism_products::sourceAtom(s.doc,ref.id)]=ref.id;
    require(s.doc.bondBetween(product.at(carbon),product.at(donor))!=kInvalidObjectId&&s.doc.bondBetween(product.at(carbon),product.at(leaving))==kInvalidObjectId,"new C--N cycle and disconnected benzylamine preserved");
    auto local=studio_local_cleanup::scope(s.doc,source,s.selected);require(!local.newCycles.empty()&&local.movable.count(product.at(donor))&&local.movable.count(product.at(carbon)),"new ring remains movable despite cyclic topology");
    auto q=studio_local_cleanup::quality(s.doc,local);std::ofstream(dir+"/ring-cleanup-quality.txt")<<q.crowd<<" "<<q.shape;require(q.crowd<1e-5,"new ring has no bond crossings or label intersections");
    for(const auto& cycle:local.newCycles){require(cycle.size()==6,"cyclization creates six-member ring");for(size_t i=0;i<cycle.size();++i){auto a=s.doc.atoms().alive(cycle[(i+cycle.size()-1)%cycle.size()])->position-s.doc.atoms().alive(cycle[i])->position,b=s.doc.atoms().alive(cycle[(i+1)%cycle.size()])->position-s.doc.atoms().alive(cycle[i])->position;require(std::abs(dot(a,b)/(length(a)*length(b))+.5)<.08,"new six-member ring has regular visible corners");}}
    // Exercise the native polygon fallback explicitly, including a folded
    // vertex on a non-neighbour, without depending on backend availability.
    Document folded=s.doc;const auto& cycle=local.newCycles.front();auto it=std::find(cycle.begin(),cycle.end(),product.at(donor));require(it!=cycle.end(),"terminal N belongs to new cycle");size_t index=size_t(it-cycle.begin());folded.setAtomPosition(product.at(donor),folded.atoms().alive(cycle[(index+3)%cycle.size()])->position);auto bad=studio_local_cleanup::quality(folded,local);require(bad.crowd>0,"folded cycle reproduces bond and label collisions");require(studio_local_cleanup::rebuildNewCycles(folded,local),"native fallback reconstructs anchored new cycle");require(studio_local_cleanup::quality(folded,local).crowd<1e-5,"native fallback removes folded-cycle collisions");for(auto id:local.atoms)if(!local.movable.count(id))require(folded.atoms().alive(id)->position==s.doc.atoms().alive(id)->position,"native reconstruction fixes every retained frame atom");
    // A double N--N bond in the newly formed ring does not invoke the acyclic
    // E/Z lock that used to freeze the entire closure neighbourhood.
    Document variant=s.doc;auto n=product.at(donor);ObjectId nn=kInvalidObjectId;for(auto bid:variant.incidentBonds(n)){auto b=variant.bonds().alive(bid);auto other=b->beginAtom==n?b->endAtom:b->beginAtom;if(variant.atoms().alive(other)->element==7)nn=bid;}require(nn!=kInvalidObjectId,"find N--N ring bond");variant.setBondOrder(nn,BondOrder::Double);auto alt=studio_local_cleanup::scope(variant,source,s.selected);auto nb=variant.bonds().alive(nn);require(alt.movable.count(nb->beginAtom)&&alt.movable.count(nb->endAtom),"new cyclic N=N does not freeze local cleanup");
    auto after=s.doc.digest();require(s.undo().ok()&&s.doc.digest()==before&&s.undo(true).ok()&&s.doc.digest()==after,"cyclization cleanup and fragment spacing are one undo step");
    auto ids=std::vector<ObjectId>();for(auto ref:s.selected)if(ref.kind==ObjectKind::Atom)ids.push_back(ref.id);auto parts=studio::clean_spacing::components(s.doc,ids,nullptr);std::vector<studio::clean_spacing::Component> products;for(auto p:parts)if(p.chosen)products.push_back(p);require(products.size()==2&&!studio::clean_spacing::overlaps(products[0].box,products[1].box,0),"released benzylamine is clear of the new ring");
    std::vector<ObjectRef> excerpt=s.selected;for(auto id:open)excerpt.emplace_back(ObjectKind::Atom,id);for(const auto& b:s.doc.bonds().records())if(b.isAlive()&&open.count(b.beginAtom)&&open.count(b.endAtom))excerpt.emplace_back(ObjectKind::Bond,b.id);for(const auto& a:s.doc.arrows().records())if(a.isAlive()&&a.id>=prior.doc.arrows().size())excerpt.emplace_back(ObjectKind::Arrow,a.id);Session display;require(studioio::append(s.doc,display.doc,excerpt,Vec2(),nullptr).ok(),"extract two-stage closure example");s.cancel();s.doc=display.doc;s.history.clear();s.selected.clear();s.refresh();s.fit();app.invalidate();app.screenshot(dir+"/ring-cleanup-reaction.png");require(s.save(dir+"/ring-cleanup-reaction.cdxml",true).ok(),"save editable closure example");
    std::ofstream(dir+"/new-ring-cleanup-checks.json")<<"{\"sequential_real_reaction\":true,\"new_ring_movable\":true,\"six_member_geometry\":true,\"native_folded_cycle_repair\":true,\"no_crossing\":true,\"cyclic_nn_double_guard\":true,\"released_amine_separated\":true,\"atomic_undo_redo\":true}";
}
